import{_ as o,Y as r,o as t,c as n,aq as i,H as d}from"./chunks/framework.DpyB0eAw.js";import"./chunks/theme.B8bSfJOi.js";const g=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/guide/home.md","filePath":"zh-cn/guide/home.md"}'),l={name:"zh-cn/guide/home.md"};function s(h,e,c,u,p,m){const a=r("NolebaseGitChangelog");return t(),n("div",null,[e[0]||(e[0]=i('<h1 id="introduction" tabindex="-1">介绍 <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><blockquote><p>为 Android 创造更多有用的工具扩展。</p></blockquote><h2 id="background" tabindex="-1">背景 <a class="header-anchor" href="#background" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>随着 Android 系统功能变得越来越丰富，原生 Android 开发需要学习的内容也越来越多，针对 Android 平台的各种工具依赖也是数不胜数， 但是各种问题也是层出不穷。</p><p>最初创建这个项目的缘由为我在做 Android 开发过程中遇到的一些问题，以及系统的 API 调用方式过于繁琐，所以此项目本着 “不重复造轮子” 的理论， 从 UI 到系统层面，为开发者在系统原有 API 的基础上，对功能进行扩展，并解决了一些在 Android 开发过程中遇到的 “黑盒问题” 和针对第三方 ROM 和第三方厂商定制的 “Android 系统” 以及 Kotlin 开发语言进行了优化，使得这套工具能够做到在无侵入、 原生态的情况下为开发者提供更加友好便捷的开发体验。</p><p>这个项目的问世也得益于我早期的一些 Android 项目，有大量的功能是从 <a href="https://github.com/PureReader" target="_blank" rel="noreferrer">轻享阅</a> 项目解耦合出来的。</p><h2 id="usage" tabindex="-1">用途 <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>BetterAndroid 为更现代化的 Android 开发而生，本意上为 “更好的 Android”。</p><p>我们希望这套工具库能够顺利地帮助各位开发者们加快开发速度以及提升开发质量和体验，快速地完善应用程序所需的功能。</p><h2 id="language-requirement" tabindex="-1">语言要求 <a class="header-anchor" href="#language-requirement" aria-label="Permalink to &quot;语言要求&quot;">​</a></h2><p>推荐使用 Kotlin 作为首选开发语言，本项目完全使用 Kotlin 编写，在部分内容上对 Java 做了兼容处理，但也许无法做到完全兼容。</p><p>文档全部的 Demo 示例代码都将使用 Kotlin 进行描述，如果你完全不会使用 Kotlin，那么你将有可能无法获得最佳使用体验。</p><h2 id="contribution" tabindex="-1">功能贡献 <a class="header-anchor" href="#contribution" aria-label="Permalink to &quot;功能贡献&quot;">​</a></h2><p>本项目的维护离不开各位开发者的支持和贡献，目前这个项目处于初期阶段，可能依然存在一些问题或者缺少你需要的功能， 如果可能，欢迎提交 PR 为此项目贡献你认为需要的功能或前往 <a href="https://github.com/BetterAndroid/BetterAndroid/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 向我们提出建议。</p>',14)),d(a)])}const A=o(l,[["render",s]]);export{g as __pageData,A as default};
